customCSS:
/* AutoDrive Motors site styles: dark theme, amber accent, CSS-only motion */
:root{
  --ad-bg:#0B0F14; --ad-surface:#121922; --ad-surface-2:#18212C; --ad-line:#243041;
  --ad-ink:#E8EDF3; --ad-muted:#93A1B2; --ad-accent:#F5A524; --ad-accent-dark:#D98B0B; --ad-accent-ink:#1A1204;
  --ad-glow:rgba(245,165,36,.18); --ad-ease:cubic-bezier(.2,.7,.2,1);
}

/* page frame */
body,.siteforceServiceBody,.cCenterPanel,.siteforceContentArea,.comm-layout-column{background:var(--ad-bg) !important;color:var(--ad-ink);}
.siteforceContentArea{position:relative;overflow-x:clip;}
.siteforceContentArea::before{content:"";position:absolute;inset:-20% -10% auto -10%;height:900px;pointer-events:none;
  background:radial-gradient(600px 300px at 20% 10%,rgba(245,165,36,.16),transparent 70%),radial-gradient(700px 360px at 85% 0%,rgba(59,130,246,.14),transparent 70%);
  animation:adDrift 18s ease-in-out infinite alternate;}
@keyframes adDrift{from{transform:translate3d(0,0,0)}to{transform:translate3d(-40px,30px,0)}}

/* header: dark glass bar, no search box (nothing public to search) */
.cHeaderPanel,.cHeaderOverlay,.themeHeader,.themeHeaderInner,.themeHeaderBottomRow{background:rgba(11,15,20,.85) !important;backdrop-filter:blur(10px);border-bottom:1px solid var(--ad-line);}
.cHeaderPanel{min-height:0 !important;}
.cSearchPublisher,.forceCommunitySearchBox{display:none !important;}
.cHeaderPanel .login-link,.selfServiceUserProfileMenu a{color:var(--ad-ink) !important;font-weight:600;}
.cHeaderPanel .login-link:hover{color:var(--ad-accent) !important;}
.forceCommunityThemeNav,.comm-navigation,.forceCommunityThemeNav .mainNavItem{background:var(--ad-bg) !important;border-bottom:1px solid var(--ad-line);}
.forceCommunityThemeNav a,.comm-navigation a{color:var(--ad-muted) !important;text-transform:none !important;font-weight:600;transition:color .2s;}
.forceCommunityThemeNav a:hover,.comm-navigation a:hover{color:var(--ad-ink) !important;}

/* hero headline */
.forceCommunityHeadline{position:relative;padding:72px 0 40px;text-align:center;}
.forceCommunityHeadline .headlineTitleText,.forceCommunityHeadline h1,.forceCommunityHeadline .headlineTitle{text-transform:none !important;font-size:clamp(36px,6vw,64px) !important;line-height:1.05;font-weight:800;letter-spacing:-.02em;
  background:linear-gradient(100deg,#FFFFFF 0%,#E8EDF3 45%,var(--ad-accent) 100%);-webkit-background-clip:text;background-clip:text;color:transparent !important;
  animation:adFadeUp .9s var(--ad-ease) both;}
.forceCommunityHeadline .headlineInfo,.forceCommunityHeadline .uiOutputRichText,.forceCommunityHeadline p{color:var(--ad-muted) !important;font-size:18px;max-width:640px;margin:16px auto 0;animation:adFadeUp .9s .15s var(--ad-ease) both;}
.forceCommunityHeadline::after{content:"";display:block;width:64px;height:3px;border-radius:3px;margin:28px auto 0;background:var(--ad-accent);box-shadow:0 0 24px var(--ad-glow);animation:adGrow 1s .3s var(--ad-ease) both;}
@keyframes adFadeUp{from{opacity:0;transform:translateY(24px)}to{opacity:1;transform:none}}
@keyframes adGrow{from{width:0;opacity:0}to{width:64px;opacity:1}}

/* sections */
.ad-section{max-width:1100px;margin:16px auto 56px;padding:0 4px;position:relative;}
.ad-eyebrow{font-size:12px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:var(--ad-accent) !important;margin:0 0 10px;}
.ad-h2{font-size:clamp(24px,3vw,34px);line-height:1.2;font-weight:800;letter-spacing:-.01em;color:var(--ad-ink) !important;margin:0 0 28px;}
.ad-h3{font-size:22px;font-weight:800;color:var(--ad-ink) !important;margin:0 0 8px;}
.ad-muted,.ad-muted *{color:var(--ad-muted) !important;font-size:15px;line-height:1.6;margin:0;}
.ad-cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px;}
.ad-card{position:relative;background:linear-gradient(180deg,var(--ad-surface-2),var(--ad-surface));border:1px solid var(--ad-line);border-radius:16px;padding:26px;
  transition:transform .35s var(--ad-ease),border-color .35s,box-shadow .35s;}
.ad-card:hover{transform:translateY(-6px);border-color:rgba(245,165,36,.55);box-shadow:0 18px 40px rgba(0,0,0,.45),0 0 0 1px rgba(245,165,36,.15);}
.ad-card h3,.ad-strip h3{font-size:18px;font-weight:700;margin:14px 0 8px;color:var(--ad-ink) !important;}
.ad-card p,.ad-strip p{font-size:14.5px;line-height:1.6;color:var(--ad-muted) !important;margin:0;}
.ad-card p.ad-num{display:inline-flex;align-items:center;justify-content:center;width:36px;height:36px;border-radius:10px;margin:0;
  background:rgba(245,165,36,.12);color:var(--ad-accent) !important;font-weight:800;font-size:15px;border:1px solid rgba(245,165,36,.35);}
.ad-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:18px;margin-top:18px;}
.ad-strip > div{background:var(--ad-surface);border:1px solid var(--ad-line);border-left:3px solid var(--ad-accent);border-radius:14px;padding:22px 24px;transition:transform .35s var(--ad-ease),background .35s;}
.ad-strip > div:hover{transform:translateY(-4px);background:var(--ad-surface-2);}
.ad-form-head{margin:8px 0 16px;}

/* footer */
.ad-footer{margin-top:40px;padding:36px 24px;text-align:center;border-top:1px solid var(--ad-line);background:transparent;}
.ad-footer p{margin:6px 0;color:var(--ad-muted) !important;font-size:14px;}
.ad-footer-name{font-weight:800;font-size:18px;color:var(--ad-ink) !important;letter-spacing:.02em;}

/* forms (screen flows) */
.forceCommunityFlowCommunity,.forceCommunityFlowCommunity flowruntime-flow,.forceCommunityFlowCommunity .slds-card__body,.forceCommunityFlowCommunity .flowruntimeBody{background:var(--ad-surface) !important;color:var(--ad-ink);}
.forceCommunityFlowCommunity{border:1px solid var(--ad-line) !important;border-radius:18px !important;padding:24px 26px;margin-bottom:32px;box-shadow:0 24px 60px rgba(0,0,0,.35);transition:border-color .35s,box-shadow .35s;}
.forceCommunityFlowCommunity:focus-within{border-color:rgba(245,165,36,.6) !important;box-shadow:0 24px 60px rgba(0,0,0,.45),0 0 0 4px var(--ad-glow);}
.forceCommunityFlowCommunity p,.forceCommunityFlowCommunity span,.forceCommunityFlowCommunity .slds-rich-text-editor__output{color:var(--ad-ink);}
.forceCommunityFlowCommunity .slds-form-element__label,.forceCommunityFlowCommunity legend,.forceCommunityFlowCommunity .slds-radio__label .slds-form-element__label{color:#C9D3DE !important;font-weight:600;font-size:13px;}
.forceCommunityFlowCommunity .slds-input,.forceCommunityFlowCommunity .slds-textarea,.forceCommunityFlowCommunity .slds-select,.forceCommunityFlowCommunity .slds-combobox__input,.forceCommunityFlowCommunity input,.forceCommunityFlowCommunity textarea,.forceCommunityFlowCommunity select{
  background:#0E141C !important;color:var(--ad-ink) !important;border:1px solid var(--ad-line) !important;border-radius:10px !important;min-height:44px;transition:border-color .2s,box-shadow .2s;}
.forceCommunityFlowCommunity input:focus,.forceCommunityFlowCommunity textarea:focus,.forceCommunityFlowCommunity select:focus{border-color:var(--ad-accent) !important;box-shadow:0 0 0 3px var(--ad-glow) !important;outline:none;}
.forceCommunityFlowCommunity input::placeholder,.forceCommunityFlowCommunity textarea::placeholder{color:#5F6D7E;}
.forceCommunityFlowCommunity select option{background:#0E141C;color:var(--ad-ink);}
.forceCommunityFlowCommunity .slds-radio_faux,.forceCommunityFlowCommunity .slds-radio--faux{background:#0E141C !important;border-color:#3A4A5E !important;}
.forceCommunityFlowCommunity .slds-radio input:checked + label .slds-radio_faux,.forceCommunityFlowCommunity .slds-radio [type=radio]:checked + .slds-radio__label .slds-radio_faux{border-color:var(--ad-accent) !important;}
.forceCommunityFlowCommunity .slds-radio [type=radio]:checked + .slds-radio__label .slds-radio_faux::after{background:var(--ad-accent) !important;}
.forceCommunityFlowCommunity .slds-required{color:var(--ad-accent) !important;}
.forceCommunityFlowCommunity .slds-card__footer,.forceCommunityFlowCommunity .flowruntimeNavigationBar,.forceCommunityFlowCommunity footer{background:transparent !important;border-top:1px solid var(--ad-line) !important;}
.forceCommunityFlowCommunity .slds-button_brand,.forceCommunityFlowCommunity .slds-button--brand{background:var(--ad-accent) !important;border-color:var(--ad-accent) !important;color:var(--ad-accent-ink) !important;
  border-radius:12px;padding:6px 28px;min-height:46px;font-weight:800;letter-spacing:.01em;transition:transform .2s var(--ad-ease),box-shadow .2s,background .2s;}
.forceCommunityFlowCommunity .slds-button_brand:hover,.forceCommunityFlowCommunity .slds-button--brand:hover{background:#FFB83F !important;transform:translateY(-2px);box-shadow:0 10px 26px rgba(245,165,36,.35);}
.forceCommunityFlowCommunity .slds-form-element__help,.forceCommunityFlowCommunity .slds-has-error .slds-form-element__help{color:#FF8A80 !important;}
.forceCommunityFlowCommunity .slds-button_icon,.forceCommunityFlowCommunity lightning-helptext button{color:var(--ad-muted) !important;}

/* scroll effects: sections rise and fade in as they enter the screen (CSS scroll-driven animations; browsers without support simply show everything) */
@supports (animation-timeline: view()){
  .ad-section .ad-eyebrow,.ad-section .ad-h2,.ad-card,.ad-strip > div,.ad-form-head,.forceCommunityFlowCommunity,.ad-footer{
    animation:adReveal linear both;animation-timeline:view();animation-range:entry 0% cover 28%;}
  .ad-card:nth-child(2){animation-range:entry 6% cover 32%;}
  .ad-card:nth-child(3){animation-range:entry 12% cover 36%;}
  @keyframes adReveal{from{opacity:0;transform:translateY(48px) scale(.98)}to{opacity:1;transform:none}}
}
@media (prefers-reduced-motion: reduce){
  *,*::before,*::after{animation:none !important;transition:none !important;}
}
@media (max-width:768px){
  .forceCommunityHeadline{padding:48px 0 24px;}
  .ad-card,.forceCommunityFlowCommunity{padding:18px;}
}

/* hero photo: dark road scene behind the headline */
.comm-content-header{position:relative;min-height:560px;display:flex;align-items:center;justify-content:center;
  background:linear-gradient(180deg,rgba(11,15,20,.55) 0%,rgba(11,15,20,.35) 45%,rgba(11,15,20,1) 100%),url('/sfsites/c/resource/AD_Hero_Road') center 65%/cover no-repeat !important;
  animation:adHeroZoom 1.6s var(--ad-ease) both;}
@keyframes adHeroZoom{from{background-size:auto,115%;opacity:.4}to{background-size:auto,cover;opacity:1}}
.comm-content-header .forceCommunityHeadline{padding:120px 0 80px;}
.comm-content-header .forceCommunityHeadline .headlineInfo,.comm-content-header .forceCommunityHeadline .uiOutputRichText{color:#C9D3DE !important;text-shadow:0 2px 12px rgba(0,0,0,.6);}

@media (max-width:768px){
  .comm-content-header{min-height:420px;}
}

/* softer, rounder form fields */
.forceCommunityFlowCommunity .slds-input,.forceCommunityFlowCommunity .slds-textarea,.forceCommunityFlowCommunity .slds-select,.forceCommunityFlowCommunity .slds-combobox__input,
.forceCommunityFlowCommunity input:not([type=radio]):not([type=checkbox]),.forceCommunityFlowCommunity textarea,.forceCommunityFlowCommunity select,
.forceCommunityFlowCommunity .slds-input-has-icon,.forceCommunityFlowCommunity .slds-select_container{border-radius:16px !important;}
.forceCommunityFlowCommunity input:not([type=radio]):not([type=checkbox]),.forceCommunityFlowCommunity select{min-height:48px;padding:0 18px !important;}
.forceCommunityFlowCommunity textarea{padding:14px 18px !important;min-height:110px;}
.forceCommunityFlowCommunity .slds-form-element{margin-bottom:6px;}
.forceCommunityFlowCommunity input,.forceCommunityFlowCommunity textarea,.forceCommunityFlowCommunity select{transition:border-color .25s ease,box-shadow .25s ease,background-color .25s ease !important;}
.forceCommunityFlowCommunity input:hover,.forceCommunityFlowCommunity textarea:hover,.forceCommunityFlowCommunity select:hover{border-color:#3A4A5E !important;}
.forceCommunityFlowCommunity .slds-button_brand,.forceCommunityFlowCommunity .slds-button--brand{border-radius:999px !important;padding:6px 32px;}

/* logo + name at the left of the header (one element, so they always line up) */
.cHeaderLine{align-items:center !important;}
.cHeaderLine::before{content:"AutoDrive Motors";flex:0 0 auto;display:flex;align-items:center;height:40px;margin:0 16px 0 24px;padding-left:52px;
  background:url('/sfsites/c/resource/AD_Logo') left center/40px 40px no-repeat;
  color:var(--ad-ink);font-weight:800;font-size:17px;line-height:40px;letter-spacing:.01em;white-space:nowrap;align-self:center;}
@media (max-width:768px){.cHeaderLine::before{content:"";padding-left:40px;margin-left:12px;}}
